// Designs as data: pieces, costumes, actions and wardrobe rules. Pure: no `$`, no Node.
//
// Everything a crab wears or does is described by JSON objects with a `type`:
//   piece    something drawn on the crab: it sits in one slot (contract B) and holds onto one
//            anchor of the body (contract A); drawn on the 18x14 card as it sits on the resting crab
//   costume  a set of pieces plus body and label colors
//   action   when it applies (tool, input, state), its priority, the pose and the effect drawn
//   rules    which costume each agent gets (rules first, then rotation) and text overrides
//   bundle   several of the above in one file, to share
// The built-in crew (src/builtin.ts) is written in this same format. Contract C (fit.ts) checks
// that every piece actually sits on the body before a pack is used.

import { CARD_H, CARD_W, mix, stampWith, type Put } from './canvas.ts'
import { normalizeDesignJson, resolveLegacyId } from './legacy.ts'
import { ANCHORS, BODY_LAYER, CLAY, EYES, FACE_SLOTS, POSE0, SLOTS, TAG, anchorShift, bodyAnchorMotion, bodyAnchorOffset, drawBody, type BodyLayer, type BodyStep, mirrorPose, slotLayer, turned, type Anchor, type Pose, type Slot, type BodyDef, type BodyMotion } from './rig.ts'
import type { KindDef } from './kinds.ts'

export const SLEEP_MS = 8000 // after this, a finished agent dozes instead of cheering
export const ERROR_MS = 3000 // a failed tool shows as an error this long
export const FALLBACK_COSTUME = 'other'
export const FALLBACK_ACTION = 'walk'
export const BUILTIN_ORIGIN = '(built-in)'

// ---- compiled form

export type Track<S> = { kind: 'fixed'; s: S } | { kind: 'steps'; steps: S[]; every: number } | { kind: 'at'; period: number; at: Map<number, S> }

export type Step = { d?: string; x?: number; y?: number; pal?: Record<string, number>; hidden?: boolean }

export type Layer = {
  x: number
  y: number
  drawings: Record<string, string[]>
  first: string
  pal: Record<string, number>
  anim: Record<string, Track<Step>[]> // by action id, '*' for every other action
  free: boolean
  /** An effect that may leave the card (a ball kicked away); the fit check does not hold it in. */
  leaves: boolean
}

export type Piece = {
  id: string
  name: string
  slot: Slot
  anchor: Anchor
  layers: Layer[]
  coversEyes: boolean
  free: boolean
  coversAction: string[]
  occupies: Slot[]
  /** The body it is drawn on, in that body's own coordinates; absent: drawn on the resting crab. */
  body?: string
  origin: string
  source: unknown
}

export type CostumeDef = { id: string; name: string; color: number; body: number; ownColor?: boolean; bodyId?: string; eyes?: number; pieces: string[]; origin: string; source: unknown }

export const STATES = ['asleep', 'finished', 'failed', 'blocked', 'error', 'thinking', 'working', 'starting', 'tests-ok'] as const
export type State = (typeof STATES)[number]

export type Cond = { tool?: RegExp; input?: RegExp; state?: State; chance?: number }

/** A one-shot play: drawn from its start for `ticks`, optionally passing the ball to another agent at `atTick`. */
export type PlayDef = { ticks: number; group: string; pass?: { atTick: number; to: string[] } }

export type Action = {
  id: string
  label: string
  color: number
  when: Cond[]
  priority: number
  duration: number
  pose: Track<Partial<Pose>>[]
  dim: number
  hand?: 'left' | 'right'
  effect: Layer[]
  play?: PlayDef
  origin: string
  source: unknown
}

export type Rule = {
  origin: string
  ruleIdx: number
  if: {
    type?: RegExp
    name?: RegExp
    description?: RegExp
    model?: RegExp
    prompt?: RegExp
    mode?: RegExp
    kind?: string
    from?: number
    to?: number
  }
  costume: string
  ifFree: boolean
  nickname?: string
}

export type Problem = { costume?: string; body?: string; file: string; id?: string; msg: string; fatal: boolean }

export type Pack = {
  bodies: Record<string, BodyDef>
  pieces: Record<string, Piece>
  costumes: Record<string, CostumeDef>
  actions: Record<string, Action>
  order: Action[] // by priority, highest first
  active: string[]
  rules: Rule[]
  labels: Record<string, string>
  problems: Problem[]
  rulesSource: unknown[]
  master?: string
  kinds?: Record<string, KindDef>
  rulesFiles: string[]
}

export const emptyPack = (): Pack => ({
  bodies: {},
  pieces: {},
  costumes: {},
  actions: {},
  order: [],
  active: [],
  rules: [],
  labels: {},
  problems: [],
  rulesSource: [],
  rulesFiles: [],
})

// ---- reading JSON: every field is checked, the file names the problem in English

class Bad extends Error {}
const bad = (msg: string): never => {
  throw new Bad(msg)
}

type Obj = Record<string, unknown>
const isObj = (v: unknown): v is Obj => typeof v === 'object' && v !== null && !Array.isArray(v)
const ID = /^[a-z0-9][a-z0-9._-]{0,39}$/

const str = (o: Obj, k: string, opt = false): string | undefined => {
  const v = o[k]
  if (v === undefined && opt) return undefined
  if (typeof v !== 'string' || v.trim() === '') return bad(`"${k}" must be a non-empty string`)
  return v
}
const num = (o: Obj, k: string, min: number, max: number, def?: number): number => {
  const v = o[k]
  if (v === undefined && def !== undefined) return def
  if (typeof v !== 'number' || !Number.isFinite(v) || v < min || v > max) return bad(`"${k}" must be a number between ${min} and ${max}`)
  return v
}
const bool = (o: Obj, k: string): boolean => {
  const v = o[k]
  if (v === undefined) return false
  if (typeof v !== 'boolean') return bad(`"${k}" must be true or false`)
  return v
}
const idOf = (o: Obj): string => {
  const id = str(o, 'id') as string
  if (!ID.test(id)) bad(`invalid id "${id}": use lowercase letters, digits, dot, hyphen or underscore (max 40)`)
  return id
}
const strList = (o: Obj, k: string): string[] => {
  const v = o[k]
  if (v === undefined) return []
  if (!Array.isArray(v) || v.some(x => typeof x !== 'string')) return bad(`"${k}" must be a list of strings`)
  return v as string[]
}

export const parseColor = (v: unknown, where: string): number => {
  if (typeof v !== 'string') return bad(`${where}: color must be "#rrggbb"`)
  const m = /^#([0-9a-fA-F]{6}|[0-9a-fA-F]{3})$/.exec(v.trim())
  if (!m) return bad(`${where}: "${v}" is not a valid color; use "#rrggbb"`)
  const h = m[1] as string
  const full = h.length === 3 ? h.split('').map(ch => ch + ch).join('') : h
  return parseInt(full, 16)
}

const palette = (v: unknown, where: string): Record<string, number> => {
  if (!isObj(v)) return bad(`${where}: "palette" must be a letter -> color object`)
  const out: Record<string, number> = {}
  for (const [k, c] of Object.entries(v)) {
    if (k.length !== 1 || k === '.' || k === ' ') bad(`${where}: palette keys must be single characters (got "${k}")`)
    out[k] = parseColor(c, `${where}, key "${k}"`)
  }
  return out
}

/**
 * Why a pattern could take too long to run, or null. Design files are shared, and their patterns run
 * against tool input on every tool call, so only a small, plainly linear subset is accepted:
 * - no repeated group at all (`(ab)+`, `(a?){3}`): repeat a single character or class instead;
 * - no backreferences;
 * - at most MAX_REPEATS repetitions (*, +, {n,m}) in the whole pattern, since each overlapping one
 *   multiplies the work (eight `\s*` in a row take minutes on 60 spaces);
 * - at most MAX_CHOICES ways to match: choices in sequence multiply (an optional part doubles them, a
 *   group with three alternatives triples them), alternatives of one group add up. So a long
 *   alternation like `\b(pytest|vitest|jest|…)\b` is fine, while chains like `a?a?a?…aaa…b` or
 *   `(a|a)(a|a)(a|a)…b`, which grow exponentially, are refused.
 * Character classes follow JavaScript's rules: `[]` is empty and `[^]` is any character, so the first
 * `]` always closes the class (reading it as PCRE does let `[^](a+)+]` slip through).
 */
const MAX_REPEATS = 2
const MAX_CHOICES = 64
export const unsafePattern = (src: string): string | null => {
  // the quantifier at i: [chars it spans, whether it repeats more than once]
  const quant = (i: number): [number, boolean] => {
    const ch = src[i]
    let n = 0
    let rep = false
    if (ch === '*' || ch === '+') { n = 1; rep = true }
    else if (ch === '?') n = 1
    else if (ch === '{') {
      const m = /^\{(\d+)(,(\d*))?\}/.exec(src.slice(i))
      if (m) { n = m[0].length; rep = m[2] === undefined ? Number(m[1]) > 1 : m[3] === '' || Number(m[3]) > 1 }
    }
    if (n > 0 && src[i + n] === '?') n++ // lazy
    return [n, rep]
  }
  let repeats = 0
  // ways to match, per open group: `done` adds up its finished alternatives, `cur` multiplies along the
  // alternative being read. [0] is the whole pattern.
  type Ways = { done: number; cur: number }
  const stack: Ways[] = [{ done: 0, cur: 1 }]
  const top = (): Ways => stack[stack.length - 1] as Ways
  const cap = (x: number): number => Math.min(x, 1e9)
  let i = 0
  while (i < src.length) {
    const ch = src[i] as string
    let group = false
    if (ch === '\\') {
      const nx = src[i + 1] ?? ''
      if (/[1-9]/.test(nx) || (nx === 'k' && src[i + 2] === '<')) return 'backreferences are not allowed'
      i += 2
    } else if (ch === '[') {
      i++
      while (i < src.length && src[i] !== ']') i += src[i] === '\\' ? 2 : 1
      i++
    } else if (ch === ')') {
      group = true
      i++
    } else if (ch === '(') {
      stack.push({ done: 0, cur: 1 })
      i++
      continue // nothing to repeat yet; a quantifier right after is a syntax error RegExp reports
    } else if (ch === '|') {
      const t = top()
      t.done = cap(t.done + t.cur)
      t.cur = 1
      i++
      continue
    } else i++
    const [n, rep] = quant(i)
    if (group && rep) return 'a group cannot be repeated (repeat a single character or class instead, e.g. [^;]{0,80})'
    if (rep && ++repeats > MAX_REPEATS) return `more than ${MAX_REPEATS} repetitions (*, +, {n,m}) in one pattern`
    // the item just read matches in `w` ways; optional, it also matches as nothing
    let w = 1
    if (group && stack.length > 1) { const g = stack.pop() as Ways; w = cap(g.done + g.cur) }
    if (n > 0 && !rep) w = cap(w + 1)
    top().cur = cap(top().cur * w)
    if (top().done + top().cur > MAX_CHOICES) return `too many ways to match (choices in a row multiply; at most ${MAX_CHOICES})`
    i += n
  }
  return null
}

const regex = (v: unknown, where: string): RegExp => {
  if (typeof v !== 'string' || v.length === 0 || v.length > 200) return bad(`${where}: must be a string of 1 to 200 characters`)
  const why = unsafePattern(v)
  if (why) return bad(`${where}: "${v}" could hang Claude Code on some inputs: ${why}`)
  try {
    return new RegExp(v, 'i')
  } catch {
    return bad(`${where}: "${v}" is not a valid regular expression`)
  }
}

const track = <S>(v: unknown, where: string, step: (x: unknown, w: string) => S): Track<S> => {
  if (!isObj(v)) return bad(`${where}: each track must be an object with "fixed", "steps" or "at"`)
  if ('fixed' in v) return { kind: 'fixed', s: step(v['fixed'], `${where}.fixed`) }
  if ('steps' in v) {
    const p = v['steps']
    if (!Array.isArray(p) || p.length === 0 || p.length > 48) return bad(`${where}: "steps" must be a list of 1 to 48 steps`)
    return { kind: 'steps', steps: p.map((x, i) => step(x, `${where}.steps[${i}]`)), every: num(v, 'every', 1, 30, 1) }
  }
  if ('at' in v) {
    const period = num(v, 'period', 1, 120)
    const at = v['at']
    if (!isObj(at)) return bad(`${where}: "at" must be a tick -> step object`)
    const m = new Map<number, S>()
    for (const [k, x] of Object.entries(at)) {
      const n = Number(k)
      if (!Number.isInteger(n) || n < 0 || n >= period) bad(`${where}: tick "${k}" must be between 0 and ${period - 1}`)
      m.set(n, step(x, `${where}.at.${k}`))
    }
    return { kind: 'at', period, at: m }
  }
  return bad(`${where}: each track requires "fixed", "steps" or "at"`)
}

const tracks = <S>(v: unknown, where: string, step: (x: unknown, w: string) => S): Track<S>[] => {
  if (v === undefined) return []
  if (!Array.isArray(v) || v.length > 8) return bad(`${where}: must be a list of up to 8 tracks`)
  return v.map((t, i) => track(t, `${where}[${i}]`, step))
}

const poseStep = (v: unknown, where: string): Partial<Pose> => {
  if (!isObj(v)) return bad(`${where}: a pose step must be an object`)
  const out: Partial<Pose> = {}
  for (const [k, x] of Object.entries(v)) {
    if (k === 'eyes') {
      if (!EYES.includes(x as never)) bad(`${where}: "eyes" must be one of ${EYES.join(', ')}`)
      out.eyes = x as Pose['eyes']
    } else if (k === 'bob' || k === 'legs' || k === 'armL' || k === 'leftArm' || k === 'armR' || k === 'rightArm') {
      if (x !== 0 && x !== 1) bad(`${where}: "${k}" must be 0 or 1`)
      const key = k === 'leftArm' ? 'armL' : k === 'rightArm' ? 'armR' : k
      ;(out as Record<string, number>)[key] = x as number
    } else if (k === 'lift' || k === 'jump') {
      if (typeof x !== 'number' || !Number.isInteger(x) || x < 0 || x > 2) bad(`${where}: "jump" must be 0, 1 or 2`)
      out.lift = x as number
    } else if (k === 'width') {
      if (typeof x !== 'number' || x < 0.1 || x > 1) bad(`${where}: "width" must be between 0.1 (side) and 1 (front)`)
      out.width = x as number
    } else if (k === 'facingAway') {
      if (typeof x !== 'boolean') bad(`${where}: "facingAway" must be true or false`)
      out.facingAway = x as boolean
    } else if (k === 'kick') {
      if (x !== 'left' && x !== 'right' && x !== null) bad(`${where}: "kick" must be "left", "right" or null`)
      out.kick = x as Pose['kick']
    } else if (k === 'dx' || k === 'shake') {
      if (typeof x !== 'number' || !Number.isInteger(x) || x < -1 || x > 1) bad(`${where}: "shake" must be -1, 0 or 1`)
      out.dx = x as number
    } else bad(`${where}: "${k}" is not part of a pose (bob, jump, shake, legs, leftArm, rightArm, eyes, width, facingAway, kick)`)
  }
  return out
}

const parseLayer = (v: unknown, where: string): Layer => {
  if (!isObj(v)) return bad(`${where}: a layer must be an object`)
  const drw = v['drawings']
  if (!isObj(drw) || Object.keys(drw).length === 0 || Object.keys(drw).length > 8) return bad(`${where}: "drawings" must have 1 to 8 named drawings`)
  const pal = palette(v['palette'], where)
  const drawings: Record<string, string[]> = {}
  for (const [name, rows] of Object.entries(drw)) {
    if (!Array.isArray(rows) || rows.length > CARD_H || rows.some(r => typeof r !== 'string' || r.length > CARD_W))
      bad(`${where}: drawing "${name}" must have up to ${CARD_H} rows of up to ${CARD_W} characters`)
    for (const r of rows as string[])
      for (const ch of r) if (ch !== '.' && ch !== ' ' && pal[ch] === undefined) bad(`${where}: character "${ch}" in drawing "${name}" is not in the palette`)
    drawings[name] = rows as string[]
  }
  const pos = v['pos']
  if (pos !== undefined && (!Array.isArray(pos) || pos.length !== 2 || pos.some(n => typeof n !== 'number' || !Number.isInteger(n) || n < -4 || n > 22)))
    bad(`${where}: "pos" must be [x, y] on the 18x14 card`)
  const [x, y] = (pos as [number, number] | undefined) ?? [0, 0]
  const step = (s: unknown, w: string): Step => {
    if (!isObj(s)) return bad(`${w}: a step must be an object`)
    const out: Step = {}
    for (const [k, val] of Object.entries(s)) {
      if (k === 'd') {
        if (typeof val !== 'string' || !drawings[val]) bad(`${w}: drawing "${String(val)}" does not exist in this layer`)
        out.d = val as string
      } else if (k === 'x' || k === 'y') {
        if (typeof val !== 'number' || !Number.isInteger(val) || Math.abs(val) > 24) bad(`${w}: "${k}" must be an integer between -24 and 24`)
        out[k] = val as number
      } else if (k === 'palette') out.pal = palette(val, w)
      else if (k === 'hidden') {
        if (typeof val !== 'boolean') bad(`${w}: "hidden" must be true or false`)
        out.hidden = val as boolean
      } else bad(`${w}: "${k}" is not part of a step (d, x, y, palette, hidden)`)
    }
    return out
  }
  const anim: Record<string, Track<Step>[]> = {}
  const a = v['anim']
  if (a !== undefined) {
    if (!isObj(a)) bad(`${where}: "anim" must be an action -> tracks object`)
    for (const [k, t] of Object.entries(a as Obj)) anim[k] = tracks(t, `${where}.anim.${k}`, step)
  }
  return { x, y, drawings, first: Object.keys(drawings)[0] as string, pal, anim, free: bool(v, 'free'), leaves: bool(v, 'leaves') }
}

const parseLayers = (v: unknown, where: string, max = 6): Layer[] => {
  if (!Array.isArray(v) || v.length === 0 || v.length > max) return bad(`${where}: must be a list of 1 to ${max} layers`)
  return v.map((c, i) => parseLayer(c, `${where}[${i}]`))
}

const parseSlot = (v: unknown, where: string): Slot => {
  if (!SLOTS.includes(v as Slot)) return bad(`${where}: slot "${String(v)}" does not exist (${SLOTS.join(', ')})`)
  return v as Slot
}

const parsePiece = (o: Obj, origin: string): Piece => {
  const id = idOf(o)
  const anchor = o['anchor']
  if (!ANCHORS.includes(anchor as Anchor)) bad(`"anchor" must be one of ${ANCHORS.join(', ')}`)
  const occupies = strList(o, 'occupies').map((s, i) => parseSlot(s, `occupies[${i}]`))
  return {
    id,
    name: str(o, 'name', true) ?? id,
    slot: parseSlot(o['slot'], 'slot'),
    anchor: anchor as Anchor,
    layers: parseLayers(o['layers'], 'layers'),
    coversEyes: bool(o, 'coversEyes'),
    free: bool(o, 'free'),
    coversAction: strList(o, 'coversAction'),
    occupies,
    ...(str(o, 'body', true) ? { body: str(o, 'body') as string } : {}),
    origin,
    source: o,
  }
}

const BODY_MOTIONS: readonly BodyMotion[] = ['body', 'ground', 'claw.left', 'claw.right', 'card']
const parseBody = (o: Obj, origin: string): BodyDef => {
  const coord = (v: unknown, where: string): { x: number; y: number } => {
    if (!isObj(v)) return bad(`${where}: must be an { x, y } object`)
    const x = num(v, 'x', 0, CARD_W - 1)
    const y = num(v, 'y', 0, CARD_H - 1)
    if (!Number.isInteger(x) || !Number.isInteger(y)) bad(`${where}: coordinates must be integers`)
    return { x, y }
  }
  const motion = (v: unknown): BodyMotion => {
    if (!BODY_MOTIONS.includes(v as BodyMotion)) return bad('body motion must be body, ground, claw.left, claw.right or card')
    return v as BodyMotion
  }
  // the body's own fixed colors: one character each, beside the H/B/S roles that follow the costume's color
  const palette: Record<string, number> = {}
  if (o['palette'] !== undefined) {
    const pal = o['palette']
    if (!isObj(pal) || Object.keys(pal).length > 12) return bad('body palette must map up to 12 characters to "#rrggbb" colors')
    for (const [k, v] of Object.entries(pal)) {
      if (k.length !== 1 || 'HBS. '.includes(k)) bad(`body palette key "${k}" must be one character other than H, B, S, dot or space`)
      palette[k] = parseColor(v, `palette.${k}`)
    }
  }
  const allowed = new Set(['H', 'B', 'S', '.', ' ', ...Object.keys(palette)])
  const raw = o['layers']
  if (!Array.isArray(raw) || raw.length < 1 || raw.length > 64) return bad('body layers must contain 1 to 64 drawings')
  const layers = raw.map((v, i) => {
    if (!isObj(v)) return bad(`body layer ${i}: must be an object`)
    const point = coord(v, `body layer ${i}`)
    const rows = strList(v, 'rows')
    if (rows.length < 1 || rows.length > CARD_H || rows.some(row => row.length < 1 || row.length > CARD_W || [...row].some(ch => !allowed.has(ch)))) bad('body rows must contain 1 to 14 rows of 1 to 18 pixels: H, B, S, dot, space or a body palette character')
    if (rows.length + point.y > CARD_H || rows.some(row => row.length + point.x > CARD_W)) bad('body layer exceeds the resting card')
    const when: { legs?: 0 | 1; kick?: ('left' | 'right' | 'none')[] } = {}
    if (v['when'] !== undefined) {
      const w = v['when']
      if (!isObj(w) || Object.keys(w).some(k => k !== 'legs' && k !== 'kick')) return bad('body layer when accepts legs and kick only')
      if (w['legs'] !== undefined) {
        if (w['legs'] !== 0 && w['legs'] !== 1) bad('body legs must be 0 or 1')
        when.legs = w['legs'] as 0 | 1
      }
      if (w['kick'] !== undefined) {
        const kicks = strList(w, 'kick')
        if (kicks.length < 1 || kicks.some(k => !['left', 'right', 'none'].includes(k))) bad('body kick must list left, right or none')
        when.kick = kicks as ('left' | 'right' | 'none')[]
      }
    }
    // other drawings of this layer, and per-action tracks that pick them or shift the layer (an ear twitch)
    const frames: Record<string, string[]> = {}
    if (v['frames'] !== undefined) {
      const f = v['frames']
      if (!isObj(f) || Object.keys(f).length > 8) return bad(`body layer ${i}: "frames" must name up to 8 drawings`)
      for (const [name, fr] of Object.entries(f)) {
        if (!Array.isArray(fr) || fr.length < 1 || fr.length > CARD_H || fr.some(r => typeof r !== 'string' || r.length < 1 || r.length > CARD_W || [...r].some(ch => !allowed.has(ch))))
          bad(`body layer ${i}: frame "${name}" must hold 1 to 14 rows of body pixels`)
        frames[name] = fr as string[]
      }
    }
    const step = (s: unknown, w: string): BodyStep => {
      if (!isObj(s)) return bad(`${w}: a step must be an object`)
      const out: BodyStep = {}
      for (const [k, val] of Object.entries(s)) {
        if (k === 'd') {
          if (typeof val !== 'string' || !Object.hasOwn(frames, val)) bad(`${w}: frame "${String(val)}" does not exist in this layer`)
          out.d = val as string
        } else if (k === 'x' || k === 'y') {
          if (typeof val !== 'number' || !Number.isInteger(val) || Math.abs(val) > 3) bad(`${w}: "${k}" must be an integer between -3 and 3`)
          out[k] = val as number
        } else if (k === 'hidden') {
          if (typeof val !== 'boolean') bad(`${w}: "hidden" must be true or false`)
          out.hidden = val as boolean
        } else bad(`${w}: "${k}" is not part of a body step (d, x, y, hidden)`)
      }
      return out
    }
    let anim: Record<string, Track<BodyStep>[]> | undefined
    if (v['anim'] !== undefined) {
      const a = v['anim']
      if (!isObj(a)) return bad(`body layer ${i}: "anim" must be an action -> tracks object`)
      anim = {}
      for (const [k, t] of Object.entries(a)) anim[k] = tracks(t, `body layer ${i}.anim.${k}`, step)
    }
    return { ...point, rows, motion: motion(v['motion']), when, ...(Object.keys(frames).length ? { frames } : {}), ...(anim ? { anim } : {}) }
  })
  const a = o['anchors']
  if (!isObj(a)) return bad('body anchors must define every named anchor')
  const anchors = {} as BodyDef['anchors']
  for (const key of ANCHORS) {
    const v = a[key]
    const point = coord(v, `body anchor ${key}`)
    anchors[key] = { ...point, motion: motion(isObj(v) ? v['motion'] : undefined) }
  }
  if (anchors.card.x !== 0 || anchors.card.y !== 0 || anchors.card.motion !== 'card') bad('card anchor must stay fixed at 0, 0')
  const arms = o['armLift']
  if (!isObj(arms)) return bad('body armLift must define left and right displacements')
  const left = num(arms, 'left', -4, 4), right = num(arms, 'right', -4, 4)
  if (!Number.isInteger(left) || !Number.isInteger(right)) bad('body armLift must contain integers')
  const e = o['eyes']
  if (!isObj(e) || !Array.isArray(e['points']) || e['points'].length < 1 || e['points'].length > 8) return bad('body eyes must define 1 to 8 points')
  const eyes = { points: e['points'].map(v => coord(v, 'body eye')), height: num(e, 'height', 1, 3), blink: num(e, 'blink', 0, 2), look: num(e, 'look', 0, 2),
    ...(e['color'] !== undefined ? { color: parseColor(e['color'], 'eyes.color') } : {}) }
  if (![eyes.height, eyes.blink, eyes.look].every(Number.isInteger)) bad('body eye dimensions must be integers')
  return { id: idOf(o), name: str(o, 'name') as string, layers, anchors, armLift: { left, right }, eyes,
    ...(o['color'] !== undefined ? { color: parseColor(o['color'], 'color') } : {}),
    ...(Object.keys(palette).length ? { palette } : {}), origin, source: o }
}

const parseCostume = (o: Obj, origin: string): CostumeDef => {
  const id = idOf(o)
  const bodyObj = o['body']
  if (bodyObj !== undefined && !isObj(bodyObj)) bad('"body" must be an object { "color": "#rrggbb", "eyes": "#rrggbb" }')
  const body = isObj(bodyObj) ? bodyObj : {}
  const pieces = strList(o, 'pieces')
  if (pieces.length > 9) bad('a costume can have at most 9 pieces')
  return {
    id,
    name: str(o, 'name') as string,
    color: parseColor(o['color'], 'color'),
    ...(str(body, 'id', true) ? { bodyId: str(body, 'id') as string } : {}),
    body: body['color'] !== undefined ? parseColor(body['color'], 'body.color') : CLAY,
    ...(body['color'] !== undefined ? { ownColor: true } : {}),
    ...(body['eyes'] !== undefined ? { eyes: parseColor(body['eyes'], 'body.eyes') } : {}),
    pieces,
    origin,
    source: o,
  }
}

const parseCond = (v: unknown, where: string): Cond => {
  if (!isObj(v)) return bad(`${where}: a condition must be an object`)
  const out: Cond = {}
  for (const [k, x] of Object.entries(v)) {
    if (k === 'tool') out.tool = new RegExp(`^(?:${regex(x, `${where}.tool`).source})$`, 'i')
    else if (k === 'input') out.input = regex(x, `${where}.input`)
    else if (k === 'state') {
      if (!STATES.includes(x as State)) bad(`${where}: "state" must be one of ${STATES.join(', ')}`)
      out.state = x as State
    } else if (k === 'chance') {
      if (typeof x !== 'number' || x <= 0 || x > 1) bad(`${where}: "chance" must be a probability per second between 0 and 1 (e.g. 0.03 ≈ once every 30 s)`)
      out.chance = x as number
    } else bad(`${where}: "${k}" is not a valid condition field (tool, input, state, chance)`)
  }
  if (!out.tool && !out.input && !out.state) bad(`${where}: condition requires tool, input or state`)
  return out
}

const parsePlay = (v: unknown, id: string): PlayDef => {
  if (!isObj(v)) return bad('"play" must be { "ticks": n, "group": "name", "pass": { "atTick": n, "to": "id" | ["id", ...] } }')
  const ticks = num(v, 'ticks', 2, 240)
  const group = str(v, 'group', true) ?? id
  const pass = v['pass']
  if (pass === undefined) return { ticks, group }
  if (!isObj(pass)) return bad('"play.pass" must be { "atTick": n, "to": "id" | ["id", ...] }')
  const r = pass['to']
  const to = typeof r === 'string' ? [r] : Array.isArray(r) && r.length > 0 && r.every(x => typeof x === 'string') ? (r as string[]) : bad('"play.pass.to" must be another play id or a list of play ids')
  const atTickKey = 'atTick' in pass ? 'atTick' : 'at'
  return { ticks, group, pass: { atTick: num(pass, atTickKey, 0, ticks - 1), to } }
}

const parseAction = (o: Obj, origin: string): Action => {
  const id = idOf(o)
  const when = o['when']
  const conds = when === undefined ? [] : Array.isArray(when) ? when.map((c, i) => parseCond(c, `when[${i}]`)) : [parseCond(when, 'when')]
  const hand = o['hand']
  if (hand !== undefined && hand !== 'left' && hand !== 'right') bad('"hand" must be "left" or "right"')
  return {
    id,
    label: str(o, 'label') as string,
    color: parseColor(o['color'], 'color'),
    when: conds,
    priority: num(o, 'priority', 0, 1000, 60),
    duration: num(o, 'duration', 0, 30000, 0),
    pose: tracks(o['pose'], 'pose', poseStep),
    dim: num(o, 'dim', 0, 1, 0),
    ...(hand ? { hand: hand as 'left' | 'right' } : {}),
    effect: o['effect'] === undefined ? [] : parseLayers(o['effect'], 'effect'),
    ...(o['play'] !== undefined ? { play: parsePlay(o['play'], id) } : {}),
    origin,
    source: o,
  }
}

const MD = /^(\d\d)-(\d\d)$/
const monthDay = (v: unknown, where: string): number => {
  const m = typeof v === 'string' ? MD.exec(v) : null
  const n = m ? Number(m[1]) * 100 + Number(m[2]) : NaN
  if (!m || Number(m[1]) < 1 || Number(m[1]) > 12 || Number(m[2]) < 1 || Number(m[2]) > 31) return bad(`${where}: date must be "MM-DD" (e.g. "12-24")`)
  return n
}

const parseRules = (o: Obj, origin = 'rules'): { active?: string[]; rules: Rule[]; labels: Record<string, string>; master?: string; defaultBody?: string; kinds?: Record<string, KindDef> } => {
  const master = str(o, 'master', true)
  const kinds: Record<string, KindDef> = {}
  const rawKinds = o['kinds']
  if (rawKinds !== undefined) {
    if (!isObj(rawKinds)) bad('"kinds" must be a kind -> { words, description } object')
    for (const [k, v] of Object.entries(rawKinds as Obj) as [string, unknown][]) {
      if (!ID.test(k)) bad(`kinds.${k}: kind identifier must be lowercase alphanumeric, dash, dot or underscore (got "${k}")`)
      if (!isObj(v)) { bad(`kinds.${k}: must be an object with "words": [...]`); continue }
      const rawWords: unknown[] = Array.isArray(v['words']) ? v['words'] : []
      if (rawWords.length === 0) bad(`kinds.${k}: "words" must be a non-empty list of regular expressions`)
      const words = rawWords.map((w: unknown, idx: number) => regex(w, `kinds.${k}.words[${idx}]`))
      const desc = str(v, 'description', true)
      kinds[k] = { words, ...(desc ? { description: desc } : {}) }
    }
  }
  const list = o['rules']
  if (list !== undefined && !Array.isArray(list)) bad('"rules" must be a list')
  const rules = ((list as unknown[] | undefined) ?? []).map((r, i): Rule => {
    const w = `rules[${i}]`
    if (!isObj(r) || !isObj(r['if'])) return bad(`${w}: each rule must be { "if": {...}, "costume": "id" }`)
    const cond = r['if'] as Obj
    const out: Rule['if'] = {}
    for (const [k, v] of Object.entries(cond)) {
      if (k === 'type' || k === 'name' || k === 'description' || k === 'model' || k === 'prompt' || k === 'mode') {
        out[k] = regex(v, `${w}.if.${k}`)
      } else if (k === 'kind') {
        const kd = str(cond, 'kind') as string
        if (!ID.test(kd)) bad(`${w}.if.kind: must be an identifier (got "${kd}")`)
        out.kind = kd
      } else if (k === 'from' || k === 'to') {
        out[k] = monthDay(v, `${w}.if.${k}`)
      } else {
        bad(`${w}.if: "${k}" is not a valid criterion (type, name, description, model, prompt, mode, kind, from, to)`)
      }
    }
    if ((out.from === undefined) !== (out.to === undefined)) bad(`${w}.if: "from" and "to" must be used together`)
    return {
      origin,
      ruleIdx: i + 1,
      if: out,
      costume: str(r, 'costume') as string,
      ifFree: bool(r, 'ifFree'),
      ...(str(r, 'nickname', true) ? { nickname: str(r, 'nickname') as string } : {}),
    }
  })
  const labels: Record<string, string> = {}
  const t = o['labels']
  if (t !== undefined) {
    if (!isObj(t)) bad('"labels" must be an action -> string object')
    for (const [k, v] of Object.entries(t as Obj)) {
      if (typeof v !== 'string' || v.length > 24) bad(`labels.${k}: must be a string of up to 24 characters`)
      labels[k] = v as string
    }
  }
  return {
    ...(o['active'] !== undefined ? { active: strList(o, 'active') } : {}),
    rules,
    labels,
    ...(master ? { master } : {}),
    ...(str(o, 'defaultBody', true) ? { defaultBody: str(o, 'defaultBody') as string } : {}),
    ...(Object.keys(kinds).length > 0 ? { kinds } : {}),
  }
}

// ---- building a pack from files (over a base pack: same id replaces)

export type DesignFile = { file: string; text?: string; json?: unknown }

export const compilePack = (files: readonly DesignFile[], base: Pack = emptyPack()): Pack => {
  const p: Pack = {
    bodies: { ...base.bodies },
    pieces: { ...base.pieces },
    costumes: { ...base.costumes },
    actions: { ...base.actions },
    order: [],
    active: [...base.active],
    rules: [...base.rules],
    labels: { ...base.labels },
    problems: [],
    rulesSource: [...base.rulesSource],
    ...(base.master ? { master: base.master } : {}),
    kinds: { ...(base.kinds ?? {}) },
    rulesFiles: [...base.rulesFiles],
  }
  const userRules: Rule[] = []
  const take = (raw: unknown, file: string): void => {
    const o = normalizeDesignJson(raw)
    if (!isObj(o)) return void p.problems.push({ file, msg: 'not a JSON object with "type"', fatal: true })
    const type = o['type']
    const id = typeof o['id'] === 'string' ? (o['id'] as string) : undefined
    try {
      if (type === 'bundle' || type === 'pack') {
        const items = o['items']
        if (!Array.isArray(items)) bad('a bundle requires "items": [...]')
        for (const it of items as unknown[]) take(it, file)
      } else if (type === 'body') {
        const x = parseBody(o, file)
        p.bodies[x.id] = x
      } else if (type === 'piece') {
        const x = parsePiece(o, file)
        p.pieces[x.id] = x
      } else if (type === 'costume') {
        const x = parseCostume(o, file)
        p.costumes[x.id] = x
      } else if (type === 'action') {
        const x = parseAction(o, file)
        p.actions[x.id] = x
      } else if (type === 'rules') {
        const r = parseRules(o, file)
        if (r.active) p.active = r.active
        if (r.master) p.master = r.master
        if (r.defaultBody) p.problems.push({ file, msg: `"defaultBody" is no longer read: each costume names its own body with "body": { "id": "${r.defaultBody}" }`, fatal: false })
        if (r.kinds) Object.assign(p.kinds!, r.kinds)
        userRules.push(...r.rules)
        Object.assign(p.labels, r.labels)
        p.rulesSource.push(o)
        if (!p.rulesFiles.includes(file)) p.rulesFiles.push(file)
      } else bad(`"type" must be body, piece, costume, action, rules or bundle (got "${String(type)}")`)
    } catch (e) {
      if (!(e instanceof Bad)) throw e
      p.problems.push({ file, ...(id ? { id } : {}), msg: e.message, fatal: true })
    }
  }
  for (const f of files) {
    let json = f.json
    if (json === undefined) {
      try {
        json = JSON.parse(f.text ?? '')
      } catch (e) {
        p.problems.push({ file: f.file, msg: `malformed JSON: ${(e as Error).message}`, fatal: true })
        continue
      }
    }
    take(json, f.file)
  }
  // the user's rules are tried before the built-in ones
  p.rules = [...userRules, ...p.rules]
  return link(p)
}

/** Cross-references: costumes name pieces that exist, one piece per slot, nothing under what another covers. */
const link = (p: Pack): Pack => {
  for (const d of Object.values(p.costumes)) {
    const missing = d.pieces.filter(id => !p.pieces[id])
    const used = new Map<Slot, string>()
    const problems: string[] = missing.map(id => `piece "${id}" does not exist`)
    if (d.bodyId && !Object.hasOwn(p.bodies, d.bodyId)) problems.push(`body "${d.bodyId}" does not exist`)
    const on = d.bodyId ?? 'crab'
    for (const id of d.pieces) {
      const drawnOn = p.pieces[id]?.body
      if (drawnOn && drawnOn !== on) problems.push(`piece "${id}" is drawn for body "${drawnOn}", not "${on}"`)
    }
    for (const id of d.pieces) {
      const pz = p.pieces[id]
      if (!pz) continue
      for (const s of [pz.slot, ...pz.occupies]) {
        const other = used.get(s)
        if (other) problems.push(`"${id}" and "${other}" both use slot "${s}"`)
        else used.set(s, id)
      }
    }
    if (problems.length > 0) {
      for (const msg of problems) p.problems.push({ file: d.origin, id: d.id, msg, fatal: true })
      delete p.costumes[d.id]
    }
  }
  if (p.master && !p.costumes[p.master]) p.problems.push({ file: 'rules', msg: `"master" costume "${p.master}" does not exist`, fatal: false })
  for (const r of p.rules) {
    if (!p.costumes[r.costume]) p.problems.push({ file: r.origin, msg: `a rule uses costume "${r.costume}", which does not exist`, fatal: false })
    if (r.if.kind && (!p.kinds || !p.kinds[r.if.kind])) p.problems.push({ file: r.origin, msg: `a rule uses kind "${r.if.kind}", which is not defined in "kinds"`, fatal: false })
  }
  for (const a of p.active) if (!p.costumes[a]) p.problems.push({ file: 'rules', msg: `"active" includes "${a}", which does not exist`, fatal: false })
  for (const a of Object.values(p.actions)) {
    for (const to of a.play?.pass?.to ?? [])
      if (!p.actions[to]?.play) p.problems.push({ file: a.origin, id: a.id, msg: `passes the ball to "${to}", which is not a play`, fatal: false })
  }
  const known = new Set(Object.keys(p.actions))
  for (const pz of Object.values(p.pieces))
    for (const c of pz.layers) for (const k of Object.keys(c.anim)) if (k !== '*' && !known.has(k)) p.problems.push({ file: pz.origin, id: pz.id, msg: `animates action "${k}", which does not exist`, fatal: false })
  p.order = Object.values(p.actions).sort((a, b) => b.priority - a.priority || a.id.localeCompare(b.id))
  return p
}

/** Removes pieces (and the costumes that use them) after a failed fit check, keeping the reasons. */
export const without = (p: Pack, pieces: ReadonlySet<string>, problems: Problem[]): Pack => {
  if (pieces.size === 0 && problems.length === 0) return p
  const keptPieces = Object.fromEntries(Object.entries(p.pieces).filter(([id]) => !pieces.has(id)))
  const keptCostumes = Object.fromEntries(Object.entries(p.costumes).filter(([, d]) => !d.pieces.some(id => pieces.has(id))))
  for (const d of Object.values(p.costumes))
    if (!keptCostumes[d.id]) p.problems.push({ file: d.origin, id: d.id, msg: `not used: wears ${d.pieces.filter(id => pieces.has(id)).join(', ')}, which did not pass the fit check`, fatal: true })
  return { ...p, pieces: keptPieces, costumes: keptCostumes, problems: [...p.problems, ...problems] }
}

// ---- tracks

const mod = (n: number, m: number): number => ((n % m) + m) % m

export const evalTracks = <S extends object>(ts: readonly Track<S>[], t: number, merge: (a: S, b: S) => S, start: S): S => {
  let out = start
  for (const tr of ts) {
    const s = tr.kind === 'fixed' ? tr.s : tr.kind === 'steps' ? tr.steps[mod(Math.floor(t / tr.every), tr.steps.length)] : tr.at.get(mod(t, tr.period))
    if (s) out = merge(out, s)
  }
  return out
}

const mergeStep = (a: Step, b: Step): Step => ({ ...a, ...b, ...(a.pal || b.pal ? { pal: { ...a.pal, ...b.pal } } : {}) })

export const poseOf = (a: Action | undefined, t: number): Pose => (a ? (evalTracks<Partial<Pose>>(a.pose, t, (x, y) => ({ ...x, ...y }), POSE0) as Pose) : POSE0)

const stepOf = (c: Layer, action: string, t: number): Step => evalTracks(c.anim[action] ?? c.anim['*'] ?? [], t, mergeStep, {})

const drawLayer = (put: Put, ox: number, oy: number, c: Layer, off: { x: number; y: number }, action: string, t: number, tag: string, free = false): void => {
  const s = stepOf(c, action, t)
  if (s.hidden) return
  const rows = c.drawings[s.d ?? c.first] ?? []
  stampWith(put, ox + c.x + off.x + (s.x ?? 0), oy + c.y + off.y + (s.y ?? 0), rows, s.pal ? { ...c.pal, ...s.pal } : c.pal, c.leaves ? TAG.leaves(tag) : free || c.free ? TAG.free(tag) : tag)
}

// ---- drawing one agent

/** A body layer's step for this action and tick: its own tracks for the action, else for every action. */
const bodyStepOf = (action: string, t: number) => (layer: BodyLayer): BodyStep => {
  const anim = layer.anim as Record<string, Track<BodyStep>[]> | undefined
  return anim ? evalTracks(anim[action] ?? anim['*'] ?? [], t, (a, b) => ({ ...a, ...b }), {}) : {}
}

/** A costume's body: the one it names, else the crab. There is no crew-wide default. */
export const effectiveBodyId = (pack: Pack, costume: string): string => pack.costumes[costume]?.bodyId ?? 'crab'

export type Plan = { rig?: BodyDef; pose: Pose; mirror: boolean; hidden: Set<string>; effect: boolean; pieces: Piece[]; body: number }

/** Decides what is drawn: the pose, which pieces, whether the effect moves to the other claw. */
export const planOf = (pack: Pack, costume: string, action: string, t: number): Plan => {
  const d = pack.costumes[costume] ?? pack.costumes[resolveLegacyId('costume', costume)] ?? pack.costumes[FALLBACK_COSTUME]
  const a = pack.actions[action] ?? pack.actions[resolveLegacyId('action', action)] ?? pack.actions[FALLBACK_ACTION]
  const pieces = (d?.pieces ?? []).map(id => pack.pieces[id]).filter((x): x is Piece => x !== undefined)
  let pose = poseOf(a, t)
  const hidden = new Set<string>()
  let mirror = false
  const effect = a !== undefined && a.effect.length > 0 && !pieces.some(p => p.coversAction.includes(a.id))
  // an action that needs a claw: if the costume holds something there, use the other claw when it
  // is free, otherwise put the costume's prop away while the action lasts. Nothing is drawn twice.
  if (effect && a?.hand) {
    const own: Slot = `hand.${a.hand}`
    const other: Slot = a.hand === 'left' ? 'hand.right' : 'hand.left'
    const holds = (s: Slot) => pieces.find(p => p.slot === s || p.occupies.includes(s))
    const holder = holds(own)
    if (holder) {
      if (!holds(other)) mirror = true
      else hidden.add(holder.id)
    }
  }
  if (mirror) pose = mirrorPose(pose)
  const rig = pack.bodies[effectiveBodyId(pack, d?.id ?? costume)]
  // a costume that names no body color takes the body's own (the crab's is CLAY)
  const base = d?.ownColor ? d.body : rig?.color ?? d?.body ?? CLAY
  const body = a && a.dim > 0 ? mix(base, 0x808080, a.dim) : base
  return { rig, pose, mirror, hidden, effect, pieces, body }
}

/** Draws one agent card at (ox, oy): pieces by slot around the body, then the action's effect. */
export const renderAgent = (put: Put, ox: number, oy: number, pack: Pack, costume: string, action: string, t: number): void => {
  const d = pack.costumes[costume] ?? pack.costumes[resolveLegacyId('costume', costume)] ?? pack.costumes[FALLBACK_COSTUME]
  const a = pack.actions[action] ?? pack.actions[resolveLegacyId('action', action)] ?? pack.actions[FALLBACK_ACTION]
  const pl = planOf(pack, costume, action, t)
  const actionId = a?.id ?? action
  // turning squeezes the body and everything it wears together; from behind, nothing on the face shows
  const body = turned(put, ox, pl.pose)
  const layers = pl.pieces
    .filter(p => !pl.hidden.has(p.id) && !(pl.pose.facingAway && FACE_SLOTS.includes(p.slot)))
    .sort((x, y) => slotLayer(x.slot) - slotLayer(y.slot))
  let bodyDrawn = false
  for (const p of layers) {
    if (!bodyDrawn && slotLayer(p.slot) > BODY_LAYER) {
      if (pl.rig) drawBody(body, ox, oy, pl.body, pl.pose, pl.rig, d?.eyes, bodyStepOf(actionId, t))
      bodyDrawn = true
    }
    // a piece drawn for this body moves with its anchor; one drawn on the crab moves onto this body first
    const off = !pl.rig ? { x: 0, y: 0 } : p.body ? bodyAnchorMotion(pl.rig, p.anchor, pl.pose) : bodyAnchorOffset(pl.rig, p.anchor, pl.pose)
    for (const c of p.layers) drawLayer(body, ox, oy, c, off, actionId, t, TAG.piece(p.id), p.free)
  }
  if (!bodyDrawn && pl.rig) drawBody(body, ox, oy, pl.body, pl.pose, pl.rig, d?.eyes, bodyStepOf(actionId, t))
  if (pl.effect && a) {
    // a held prop goes to the claw (or paw) this body has where the crab's is; other effects stay on the card
    const side = a.hand ? (pl.mirror ? (a.hand === 'left' ? 'right' : 'left') : a.hand) : undefined
    const sh = pl.rig && side ? anchorShift(pl.rig, `claw.${side}`) : { x: 0, y: 0 }
    const fx: Put = pl.mirror ? (x, y, col, tag) => put(ox + CARD_W - 1 - (x - ox) + sh.x, y + sh.y, col, tag) : (x, y, col, tag) => put(x + sh.x, y + sh.y, col, tag)
    for (const c of a.effect) drawLayer(fx, ox, oy, c, { x: 0, y: 0 }, actionId, t, TAG.effect(a.id))
  }
}

// ---- which action an agent shows (from recorded facts only)

export type Facts = {
  id?: string
  tests?: readonly { ok: boolean | null; at: number }[]
  status: 'running' | 'done' | 'failed' | 'killed'
  endedAt?: number
  blockers: readonly string[]
  inTool: boolean
  anim: string
  lastEventAt: number
  toolCount: number
  declaredAt?: number
  lastTool?: string
  lastToolInput?: string
  lastToolAt?: number
}

const inState = (e: State, a: Facts, now: number): boolean => {
  const running = a.status === 'running'
  switch (e) {
    case 'asleep':
      return a.status === 'done' && a.endedAt !== undefined && now - a.endedAt > SLEEP_MS
    case 'finished':
      return a.status === 'done'
    case 'failed':
      return a.status === 'failed' || a.status === 'killed'
    case 'blocked':
      return running && a.blockers.length > 0
    case 'error':
      return running && !a.inTool && a.anim === 'error' && now - a.lastEventAt < ERROR_MS
    case 'thinking':
      return running && !a.inTool && (a.toolCount > 0 || a.declaredAt !== undefined)
    case 'working':
      return running && a.inTool
    case 'starting':
      return running
    case 'tests-ok': {
      const last = a.tests?.[a.tests.length - 1]
      return last !== undefined && last.ok === true && now - last.at < ERROR_MS
    }
  }
}

/** A deterministic coin per agent and second: `chance` 0.03 comes up about once every 30 s. */
const coin = (id: string, now: number, p: number): boolean => hash(`${id}:${Math.floor(now / 1000)}`) / 0x100000000 < p

const matches = (c: Cond, act: Action, a: Facts, now: number): boolean => {
  if (c.state && !inState(c.state, a, now)) return false
  if (c.chance !== undefined && !coin(a.id ?? '', now, c.chance)) return false
  if (c.tool || c.input) {
    if (a.status !== 'running' || !a.lastTool) return false
    const live = a.inTool || (act.duration > 0 && a.lastToolAt !== undefined && now - a.lastToolAt < act.duration)
    if (!live) return false
    if (c.tool && !c.tool.test(a.lastTool)) return false
    if (c.input && !c.input.test(a.lastToolInput ?? '')) return false
  }
  return true
}

/** The looping action an agent shows (plays are started by the director, never chosen here). */
export const resolveAction = (pack: Pack, a: Facts, now: number): Action | undefined =>
  pack.order.find(act => !act.play && act.when.some(c => matches(c, act, a, now))) ?? pack.actions[FALLBACK_ACTION]

/** The plays whose condition holds right now (the director starts one when this set gains a member). */
export const playsReady = (pack: Pack, a: Facts, now: number): string[] =>
  pack.order.filter(act => act.play && act.when.some(c => matches(c, act, a, now))).map(act => act.id)

/** The label of an action, with the user's text override. */
export const labelOf = (pack: Pack, act: Action | undefined): [string, number] => (act ? [pack.labels[act.id] ?? act.label, act.color] : ['●', 0x9aa0a8])

export const costumeColor = (pack: Pack, id: string): number => (pack.costumes[id] ?? pack.costumes[FALLBACK_COSTUME])?.color ?? 0x888780

// ---- which costume an agent wears: rules first, then rotation without repeats

export const hash = (s: string): number => {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619)
  return h >>> 0
}

export type Who = { id: string; type: string; description: string; name?: string; model?: string; mode?: string; prompt?: string; kind?: string }

const inDates = (cond: Rule['if'], now: number): boolean => {
  if (cond.from === undefined || cond.to === undefined) return true
  const d = new Date(now)
  const md = (d.getMonth() + 1) * 100 + d.getDate()
  return cond.from <= cond.to ? md >= cond.from && md <= cond.to : md >= cond.from || md <= cond.to
}

const ruleMatches = (r: Rule, w: Who, now: number): boolean => {
  const bare = w.type.includes(':') ? (w.type.split(':').pop() ?? w.type) : w.type
  const cond = r.if
  if (cond.type && !cond.type.test(bare) && !cond.type.test(w.type)) return false
  if (cond.name && !cond.name.test(w.name ?? '')) return false
  if (cond.description && !cond.description.test(w.description)) return false
  if (cond.model && !cond.model.test(w.model ?? '')) return false
  if (cond.mode && !cond.mode.test(w.mode ?? '')) return false
  if (cond.prompt && !cond.prompt.test((w.prompt ?? '').slice(0, 400))) return false
  if (cond.kind && cond.kind !== w.kind) return false
  return inDates(cond, now)
}

export const resolveCostume = (pack: Pack, w: Who, taken: readonly string[], now: number): { costume: string; nickname?: string; by: string } => {
  for (const r of pack.rules) {
    if (!pack.costumes[r.costume] || !ruleMatches(r, w, now)) continue
    if (r.ifFree && taken.includes(r.costume)) continue
    return { costume: r.costume, ...(r.nickname ? { nickname: r.nickname } : {}), by: `${r.origin} #${r.ruleIdx}` }
  }
  const list = pack.active.filter(id => pack.costumes[id])
  if (list.length === 0) return { costume: FALLBACK_COSTUME, by: 'fallback' }
  const start = hash(w.id) % list.length
  for (let i = 0; i < list.length; i++) {
    const c = list[(start + i) % list.length] as string
    if (!taken.includes(c)) return { costume: c, by: 'rotation' }
  }
  return { costume: list[start] as string, by: 'rotation' }
}

// ---- sharing: a costume (or piece, or action) and everything it needs, as one file

export const bundle = (pack: Pack, ids: readonly string[]): { json: unknown; missing: string[] } => {
  const items: unknown[] = []
  const seen = new Set<string>()
  const missing: string[] = []
  const add = (kind: string, id: string, src: unknown) => {
    if (seen.has(`${kind}:${id}`)) return
    seen.add(`${kind}:${id}`)
    items.push(src)
  }
  for (const rawId of ids) {
    const cId = resolveLegacyId('costume', rawId)
    const pId = resolveLegacyId('piece', rawId)
    const aId = resolveLegacyId('action', rawId)
    const d = pack.costumes[rawId] ?? pack.costumes[cId]
    const pz = pack.pieces[rawId] ?? pack.pieces[pId]
    const ac = pack.actions[rawId] ?? pack.actions[aId]
    const bd = pack.bodies[rawId]
    if (d) {
      const id = effectiveBodyId(pack, d.id)
      const src = d.source as Record<string, unknown>
      add('costume', d.id, { ...src, body: { ...(isObj(src?.['body']) ? src['body'] : {}), id } })
      if (pack.bodies[id]) add('body', id, pack.bodies[id]?.source)
      for (const p of d.pieces) if (pack.pieces[p]) add('piece', p, pack.pieces[p]?.source)
    } else if (pz) add('piece', pz.id, pz.source)
    else if (ac) add('action', ac.id, ac.source)
    else if (bd) add('body', bd.id, bd.source)
    else missing.push(rawId)
  }
  return { json: { type: 'bundle', format: 'crabbus/1', name: ids.join(', '), items }, missing }
}

files.src/panel.ts:
// The side panel's view models (the v3 panel design). Pure: no `$`; callers pass `now` and the state.
//
// Every figure comes from recorded facts. Declared progress stays "x/y stages declared", never a
// percentage of the work. A subagent's cost is an estimate (price.ts) and is always marked "≈"; the
// session total is the ledger's real figure.

import { masterCostume } from './art.ts'
import { BUILTIN } from './builtin.ts'
import { uiStatus, type Activity, type AgentRec, type BusState, type Permission } from './model.ts'
import { BUILTIN_ORIGIN, costumeColor, effectiveBodyId, type Pack, type Problem, type Rule } from './pack.ts'
import { NO_USAGE, costOf, costParts, promptTokens, windowOf, type Usage } from './price.ts'
import { paneList, shownName } from './scene.ts'
import { C, ST, agoTxt, clock, ctxColor, dur, fc, fk, fit, limitName, prog, resetClock, spark, toolColor, untilTxt, type UiStatus } from './theme.ts'

// ---- one agent

export type AgentView = {
  id: string
  /** 1-based position in the list: its hotkey. */
  idx: number
  name: string
  color: number
  role: string
  model: string
  st: UiStatus
  tool: string
  arg: string
  toolC: number
  done: number
  total: number
  bar: string
  progTxt: string
  ago: string
  ctxPct?: number
  ctxC: number
  tokTxt: string
  cost: number
  costTxt: string
  permission?: Permission
  summary: string
}

// tools the engine or this plugin use for bookkeeping: never shown as what an agent is doing
const BUS_TOOL = /^(mcp__crabbus__|SubagentHandback$)/

/** Loops the bus adopted without seeing their spawn (engine forks, hook agents): kept in bus_status, left out of the panel. */
export const panelAgents = (list: readonly AgentRec[]): AgentRec[] => list.filter(a => a.type !== 'unknown')

export const agentCost = (a: AgentRec): number => (!a.ext && a.usage ? costOf(a.usage, a.usedModel ?? a.model) : 0)

export const agentCtx = (a: AgentRec): number | undefined =>
  a.ext || a.lastPrompt === undefined ? undefined : Math.min(100, Math.round((a.lastPrompt / windowOf(a.usedModel ?? a.model)) * 100))

export const agentView = (s: BusState, a: AgentRec, idx: number, now: number, pack: Pack = BUILTIN): AgentView => {
  const st = uiStatus(s, a)
  const total = a.plan.length
  const ctxPct = agentCtx(a)
  const cost = agentCost(a)
  const permission = (s.pending ?? []).find(p => p.agentId === a.id)
  const shown = a.lastTool && !BUS_TOOL.test(a.lastTool) && a.status === 'running'
  const tool = shown ? (a.lastTool as string) : a.status === 'done' ? 'finished' : a.status !== 'running' ? a.status : a.current ? 'now' : '—'
  const arg = shown ? (a.lastToolInput ?? '') : a.status === 'done' ? 'report delivered' : (a.current ?? '')
  const summary =
    st === 'blocked' ? (permission ? `permission requested in Claude Code: ${permission.tool}` : `blocked: ${a.blockers[a.blockers.length - 1] ?? ''}`)
    : st === 'waiting' ? (a.questions.length > 0 ? `asks: ${a.questions[a.questions.length - 1]}` : 'waiting on a message')
    : st === 'done' ? `finished${a.endedAt !== undefined ? ` ${agoTxt(now - a.endedAt)}` : ''}`
    : st === 'failed' ? `ended (${a.status})${a.lastError ? `: ${a.lastError}` : ''}`
    : st === 'thinking' ? (a.current ? `now: ${a.current}` : 'reasoning about the next step')
    : `running ${a.lastTool ?? 'a tool'}${total > 0 ? ` · ${a.done} of ${total} stages` : ''}`
  return {
    id: a.id,
    idx,
    name: shownName(a),
    color: costumeColor(pack, a.costume),
    role: a.ext ? a.ext.label ?? `${a.ext.cli} · ${a.ext.profile}` : a.type,
    model: a.usedModel ?? a.model ?? 'model ?',
    st,
    tool,
    arg,
    toolC: st === 'working' ? C.mint : st === 'done' ? C.cyan : C.faint,
    done: a.done,
    total,
    bar: prog(a.done, total, 10),
    progTxt: total > 0 ? `${a.done}/${total}` : '–',
    ago: agoTxt(now - a.lastEventAt),
    ...(ctxPct !== undefined ? { ctxPct } : {}),
    ctxC: ctxColor(ctxPct ?? 0),
    tokTxt: a.tokensIn !== undefined ? `↑${fk(a.tokensIn)} ↓${fk(a.tokensOut ?? 0)}` : '↑– ↓–',
    cost,
    costTxt: a.ext ? 'subscription' : a.usage ? fc(cost, true) : '≈$–',
    ...(permission ? { permission } : {}),
    summary,
  }
}

// ---- the list

export type Filter = 'all' | 'active' | 'attention' | 'done'
export const FILTERS: readonly Filter[] = ['all', 'active', 'attention', 'done']

const inFilter = (f: Filter, st: UiStatus): boolean =>
  f === 'all' ? true
  : f === 'active' ? st === 'working' || st === 'thinking'
  : f === 'attention' ? st === 'blocked' || st === 'waiting'
  : st === 'done' || st === 'failed'

export type MasterView = {
  st: UiStatus
  tool: string
  arg: string
  delegated: string
  tokTxt: string
  cost: number
  costTxt: string
  ctxPct?: number
  ctxC: number
}

export type ActivityView = { ts: string; g: string; gc: number; name: string; color: number; text: string }

export type ListModel = {
  /** Subagents shown (filter applied), in pane order. */
  cards: AgentView[]
  /** Every listed subagent, for the delegation tree and counts. */
  all: AgentView[]
  older: number
  counts: Record<UiStatus, number>
  filters: { id: Filter; n: number }[]
  master: MasterView
  metrics: {
    stagesTxt: string
    stagesPct: number
    ctxPct?: number
    ctxC: number
    tokIn: string
    tokOut: string
    cost: number
    costTxt: string
    costSpark: string
    summary: string
    /** The account's usage windows (5h, week), most used first. */
    limits: LimitView[]
  }
  liveTools: { n: string; k: number; c: number }[]
  activity: ActivityView[]
}

const sumUsage = (us: readonly (Usage | undefined)[]): Usage =>
  us.reduce<Usage>((x, u) => (u ? { input: x.input + u.input, output: x.output + u.output, cacheRead: x.cacheRead + u.cacheRead, cacheWrite: x.cacheWrite + u.cacheWrite } : x), NO_USAGE)

export type LimitView = { name: string; pct: number; c: number; reset?: string; at?: string }

/** The account's rate-limit windows as the panel shows them: name, % used, color by fill, time to reset. */
export const limitViews = (s: BusState, now: number): LimitView[] =>
  (s.session?.limits ?? [])
    .map(l => ({
      name: limitName(l.kind),
      pct: Math.max(0, Math.min(100, l.pct)),
      c: ctxColor(l.pct),
      ...(l.resetsAt !== undefined ? { reset: untilTxt(l.resetsAt - now), at: resetClock(l.resetsAt, now) } : {}),
    }))

export const listModel = (s: BusState, now: number, opts: { filter: Filter; showAll: boolean }, pack: Pack = BUILTIN): ListModel => {
  const { shown, older } = paneList(s, now, opts.showAll)
  const all = panelAgents(shown).map((a, i) => agentView(s, a, i + 1, now, pack))
  const counts: Record<UiStatus, number> = { working: 0, thinking: 0, waiting: 0, blocked: 0, done: 0, failed: 0 }
  for (const v of all) counts[v.st]++
  const ses = s.session ?? {}
  const subs = panelAgents(Object.values(s.agents))
  const subCost = subs.reduce((x, a) => x + agentCost(a), 0)
  const masterEst = ses.usage ? costOf(ses.usage, ses.model) : 0
  // the ledger's total is real; without it, everything is an estimate
  const total = ses.costUsd ?? masterEst + subCost
  const masterCost = ses.costUsd !== undefined ? Math.max(0, ses.costUsd - subCost) : masterEst
  const running = subs.filter(a => a.status === 'running').length
  const doneSubs = subs.filter(a => a.status === 'done').length
  const masterCtx = ses.ctxPercent ?? (ses.lastPrompt !== undefined ? Math.round((ses.lastPrompt / windowOf(ses.model)) * 100) : undefined)
  const master: MasterView = {
    st: ses.inTool ? 'working' : running > 0 ? 'thinking' : 'done',
    tool: ses.lastTool ?? '—',
    arg: ses.lastToolInput ?? '',
    delegated: `${doneSubs}/${subs.length}`,
    tokTxt: ses.usage ? `↑${fk(promptTokens(ses.usage))} ↓${fk(ses.usage.output)}` : '↑– ↓–',
    cost: masterCost,
    costTxt: fc(masterCost, ses.costUsd === undefined),
    ...(masterCtx !== undefined ? { ctxPct: masterCtx } : {}),
    ctxC: ctxColor(masterCtx ?? 0),
  }
  const dn = subs.reduce((x, a) => x + Math.min(a.done, a.plan.length), 0)
  const tot = subs.reduce((x, a) => x + a.plan.length, 0)
  const every = sumUsage([ses.usage, ...subs.map(a => a.usage)])
  const tin = promptTokens(every) || subs.reduce((x, a) => x + (a.tokensIn ?? 0), 0)
  const tout = every.output || subs.reduce((x, a) => x + (a.tokensOut ?? 0), 0)
  const live = new Map<string, number>()
  for (const a of subs) if (a.status === 'running' && a.inTool && a.lastTool && !BUS_TOOL.test(a.lastTool)) live.set(a.lastTool, (live.get(a.lastTool) ?? 0) + 1)
  if (ses.inTool && ses.lastTool) live.set(ses.lastTool, (live.get(ses.lastTool) ?? 0) + 1)
  const costTxt = fc(total, ses.costUsd === undefined)
  return {
    cards: all.filter(v => inFilter(opts.filter, v.st)),
    all,
    older,
    counts,
    filters: FILTERS.map(id => ({ id, n: all.filter(v => inFilter(id, v.st)).length })),
    master,
    metrics: {
      stagesTxt: tot > 0 ? `${dn}/${tot}` : '–',
      stagesPct: tot > 0 ? Math.round((dn / tot) * 100) : 0,
      ...(masterCtx !== undefined ? { ctxPct: masterCtx } : {}),
      ctxC: ctxColor(masterCtx ?? 0),
      tokIn: fk(tin),
      tokOut: fk(tout),
      cost: total,
      costTxt,
      costSpark: spark(ses.costHist ?? []),
      summary: `${tot > 0 ? `${dn}/${tot} stages` : 'no plans'} · ${costTxt}`,
      limits: limitViews(s, now),
    },
    liveTools: [...live.entries()].map(([n, k]) => ({ n, k, c: toolColor(n) })),
    activity: activityView(s, s.activity ?? [], pack).slice(0, 5),
  }
}

export const activityView = (s: BusState, list: readonly Activity[], pack: Pack = BUILTIN): ActivityView[] =>
  list.filter(e => s.agents[e.id]?.type !== 'unknown' && !/SubagentHandback/.test(e.text)).map(e => {
    const a = s.agents[e.id]
    return { ts: clock(e.at), g: e.g ?? ST[e.st].g, gc: e.g === '✓' ? C.mint : ST[e.st].c, name: a ? shownName(a) : e.id, color: a ? costumeColor(pack, a.costume) : C.dim, text: e.text }
  })

// ---- one agent in detail

export type DetailModel = {
  v: AgentView
  pos: string
  elapsed: string
  cost: { parts: { l: string; v: string; pct: number }[]; rate: string }
  tokens: { out: string; inTxt: string; spark: string; cache: string; hit: string }
  ctx: { cells: number[]; used: string }
  timing: { start: string; last: string; avg: string; cells: number[] }
  tools: { current: string; history: { g: string; c: number; n: string; a: string; t: string }[]; count: string }
  tasks: { g: string; c: number; tc: number; t: string; strike: boolean }[]
  verified: string
  blockers: string[]
  questions: string[]
  messages: { text: string; steps: string; c: number }[]
}

export const detailModel = (s: BusState, a: AgentRec, list: readonly AgentRec[], now: number, pack: Pack = BUILTIN): DetailModel => {
  const i = Math.max(0, list.findIndex(x => x.id === a.id))
  const v = agentView(s, a, i + 1, now, pack)
  const u = a.usage ?? NO_USAGE
  const model = a.usedModel ?? a.model
  const parts = costParts(u, model)
  const total = parts.input + parts.output + parts.cacheRead + parts.cacheWrite
  const biggest = Math.max(parts.input, parts.output, parts.cacheRead, parts.cacheWrite, 1e-9)
  const elapsedMs = (a.endedAt ?? now) - a.startedAt
  const prompt = promptTokens(u)
  const window = windowOf(model)
  const used = a.ext ? 0 : a.lastPrompt ?? 0
  const filled = Math.round((used / window) * 20)
  const runs = a.toolLog ?? []
  const tl = runs.slice(-18).map(r => (r.ok === false ? C.pink : toolColor(r.tool)))
  while (tl.length < 18) tl.unshift(C.line)
  const verified = Object.keys(a.evidence).filter(k => Number(k) <= a.done).length
  return {
    v,
    pos: `${i + 1}/${list.length}`,
    elapsed: dur(elapsedMs),
    cost: {
      parts: a.ext ? [] : [['input', parts.input], ['output', parts.output], ['cache read', parts.cacheRead], ['cache write', parts.cacheWrite]].map(([l, x]) => ({ l: l as string, v: fc(x as number), pct: Math.round(((x as number) / biggest) * 100) })),
      rate: a.ext ? 'Subscription · tokens only' : a.usage ? `≈${fc(total / Math.max(1 / 60, elapsedMs / 60000))}/min · list prices` : 'no usage reported yet',
    },
    tokens: {
      out: fk(u.output || (a.tokensOut ?? 0)),
      inTxt: fk(prompt || (a.tokensIn ?? 0)),
      spark: spark(a.usageHist ?? []),
      cache: fk(u.cacheRead),
      hit: prompt > 0 ? `${Math.round((u.cacheRead / prompt) * 100)}% hit` : '–',
    },
    ctx: {
      // one cell per 5 % of the window; the 80 % cell marks where compaction starts
      cells: [...Array(20)].map((_, k) => (k < filled ? ctxColor(v.ctxPct ?? 0) : k === 16 ? 0x4a2a38 : C.line)),
      used: a.ext ? 'CLI context not reported' : a.lastPrompt !== undefined ? `${fk(used)} / ${fk(window)}` : 'no request reported yet',
    },
    timing: {
      start: clock(a.startedAt),
      last: agoTxt(now - a.lastEventAt),
      avg: a.requests ? `${(elapsedMs / a.requests / 1000).toFixed(1)}s` : '–',
      cells: tl,
    },
    tools: {
      current: a.lastTool ? `${a.lastTool} ${a.lastToolInput ?? ''}`.trim() : 'none yet',
      history: runs.filter(r => r.ok !== undefined).slice(-5).reverse().map(r => ({ g: r.ok ? '✓' : '✗', c: r.ok ? C.mint : C.pink, n: r.tool, a: r.arg, t: r.ms !== undefined ? `${(r.ms / 1000).toFixed(1)}s` : '' })),
      count: `${a.toolCount} tool${a.toolCount === 1 ? '' : 's'}`,
    },
    tasks: a.plan.map((t, k) => {
      const dn = k < a.done
      const cur = k === a.done && a.status === 'running'
      const ev = a.evidence[k + 1]
      return { g: dn ? '☒' : cur ? '◐' : '☐', c: dn ? C.mint : cur ? C.yellow : C.faint, tc: dn ? C.faint : cur ? C.text : C.dim, t: `${t}${ev ? `  · ${ev}` : ''}`, strike: dn }
    }),
    verified: a.done > 0 ? `verified: ${verified} of ${a.done} declared-done stage(s) carry evidence` : a.declaredAt === undefined ? 'no bus_step report yet: nothing declared' : 'no stage declared done yet',
    blockers: a.blockers,
    questions: a.questions,
    messages: s.msgs.filter(m => m.to === a.id).slice(-3).map(m => ({
      text: m.text,
      steps: [m.accepted ? '✓ accepted' : '✗ rejected', `${m.receivedAt !== undefined ? '✓' : '○'} delivered`, `${m.ackedAt !== undefined ? '✓' : '○'} read`, `${m.appliedAt !== undefined ? '✓' : '○'} applied`].join('  '),
      c: m.appliedAt !== undefined ? C.mint : C.lav,
    })),
  }
}

// ---- the transcript, from the agent's own messages ($.session.messages({ agentId, as: 'api' }))

export type TxBody = { p: string; t: string; c: number; bg?: number }
export type TxLine = { k: 'msg' | 'think' | 'tool' | 'user'; g: string; gc: number; head: string; hc: number; arg: string; text: string; tc: number; italic: boolean; body: TxBody[] }
export type TxTab = 'all' | 'tools' | 'reasoning'
export const TABS: readonly TxTab[] = ['all', 'tools', 'reasoning']

type Block = Record<string, unknown>
const str = (v: unknown): string => (typeof v === 'string' ? v : '')
const blocksOf = (m: unknown): Block[] => {
  const c = (m as { content?: unknown } | null)?.content
  return Array.isArray(c) ? (c.filter(b => typeof b === 'object' && b !== null) as Block[]) : typeof c === 'string' ? [{ type: 'text', text: c }] : []
}
const resultText = (b: Block): string => {
  const c = b['content']
  if (typeof c === 'string') return c
  if (Array.isArray(c)) return c.map(x => str((x as Block)['text'])).filter(Boolean).join('\n')
  return ''
}
/** What the engine adds to a tool result for the model (reminders), and terminal escapes: never the agent's work. */
const clean = (t: string): string =>
  t.replace(/<system-reminder>[\s\S]*?(<\/system-reminder>|$)/g, '').replace(/\x1b\[[0-9;?]*[A-Za-z]/g, '').replace(/[\t\r]/g, ' ').replace(/[\x00-\x08\x0b-\x1f\x7f]/g, '')

/** What a tool call was given, as one short argument: the path, command, pattern or url. */
export const toolArg = (name: string, input: unknown): string => {
  const o = (typeof input === 'object' && input !== null ? input : {}) as Record<string, unknown>
  const v = str(o['file_path']) || str(o['command']) || str(o['pattern']) || str(o['url']) || str(o['path']) || str(o['description']) || str(o['to']) || str(o['query'])
  return v ? `(${fit(v.replace(/\s+/g, ' '), 70)})` : name === 'TodoWrite' ? '' : '()'
}

const resultBody = (name: string, input: unknown, result: string, isError: boolean, w: number): TxBody[] => {
  const o = (typeof input === 'object' && input !== null ? input : {}) as Record<string, unknown>
  const lines = clean(result).split('\n').filter(l => l.trim() !== '')
  if (isError) return [{ p: '⎿', t: fit(lines[0] ?? 'error', w), c: C.pink }]
  if ((name === 'Edit' || name === 'MultiEdit') && typeof o['old_string'] === 'string') {
    const out: TxBody[] = [{ p: '⎿', t: fit(lines[0] ?? 'Updated', w), c: C.dim }]
    for (const l of str(o['old_string']).split('\n').slice(0, 3)) out.push({ p: '', t: fit(`- ${l}`, w), c: C.pink, bg: 0x2a1820 })
    for (const l of str(o['new_string']).split('\n').slice(0, 4)) out.push({ p: '', t: fit(`+ ${l}`, w), c: C.mint, bg: 0x18261c })
    return out
  }
  if (name === 'Read') return [{ p: '⎿', t: `Read ${lines.length} lines`, c: C.dim }]
  if (name === 'TodoWrite' && Array.isArray(o['todos']))
    return (o['todos'] as Block[]).slice(0, 8).map((t, k) => {
      const st = str(t['status'])
      return { p: k === 0 ? '⎿' : '', t: fit(`${st === 'completed' ? '☒' : '☐'} ${str(t['content'])}`, w), c: st === 'completed' ? C.faint : st === 'in_progress' ? C.yellow : C.text }
    })
  const shown = lines.slice(0, name === 'Bash' ? 5 : 2)
  if (shown.length === 0) return [{ p: '⎿', t: '(no output)', c: C.dim }]
  return shown.map((l, k) => ({ p: k === 0 ? '⎿' : '', t: fit(l, w), c: /✗|fail|error/i.test(l) ? C.pink : /✓|pass/i.test(l) ? C.mint : C.dim }))
}

/**
 * The agent's conversation as the panel's transcript lines: the task and the master's messages,
 * thinking, text, and each tool call with the first lines of its result (diffs for edits).
 */
export const transcriptLines = (messages: readonly unknown[], name: string, width: number): TxLine[] => {
  const w = Math.max(16, width)
  const results = new Map<string, { text: string; isError: boolean }>()
  for (const m of messages) for (const b of blocksOf(m)) if (b['type'] === 'tool_result') results.set(str(b['tool_use_id']), { text: resultText(b), isError: b['is_error'] === true })
  const out: TxLine[] = []
  const base = { head: '', hc: C.text, arg: '', text: '', tc: C.text, italic: false, body: [] as TxBody[] }
  for (const m of messages) {
    const role = (m as { role?: unknown } | null)?.role
    for (const b of blocksOf(m)) {
      const t = b['type']
      if (role === 'user' && t === 'text') {
        const text = clean(str(b['text'])).trim()
        // reminders the engine adds are not the master's words
        if (text) out.push({ ...base, k: 'user', g: '›', gc: C.faint, head: `master → ${name}  `, hc: C.master, text: fit(text.replace(/\s+/g, ' '), w * 3) })
      } else if (role === 'assistant' && t === 'thinking') {
        // models that return no summary leave the block empty: nothing to show
        const text = clean(str(b['thinking'])).trim()
        if (text) out.push({ ...base, k: 'think', g: '✻', gc: C.lav, head: 'thinking  ', hc: C.lav, text: fit(text.replace(/\s+/g, ' '), w * 3), tc: C.thought, italic: true })
      } else if (role === 'assistant' && t === 'text') {
        const text = clean(str(b['text'])).trim()
        if (text) out.push({ ...base, k: 'msg', g: '⏺', gc: C.text, text: fit(text.replace(/\s+/g, ' '), w * 4) })
      } else if (role === 'assistant' && t === 'tool_use') {
        const n = str(b['name'])
        const inp = (typeof b['input'] === 'object' && b['input'] !== null ? b['input'] : {}) as Record<string, unknown>
        if (n === 'SubagentHandback') {
          // the agent's final report to the master
          const report = clean(Object.values(inp).filter((x): x is string => typeof x === 'string').sort((x, y) => y.length - x.length)[0] ?? '').trim()
          if (report) out.push({ ...base, k: 'msg', g: '⏺', gc: C.cyan, head: 'report → master  ', hc: C.cyan, text: fit(report.replace(/\s+/g, ' '), w * 5) })
          continue
        }
        if (n === 'mcp__crabbus__bus_step') {
          // what the agent declared, in one line: the bus's DECLARED layer as it happened
          const parts: string[] = []
          if (Array.isArray(inp['plan'])) parts.push(`plan ${(inp['plan'] as unknown[]).length} stages`)
          if (typeof inp['done'] === 'number') parts.push(`done ${inp['done']}`)
          for (const k of ['current', 'question', 'blocker', 'reply', 'note'] as const) if (typeof inp[k] === 'string') parts.push(`${k}: ${inp[k] as string}`)
          if (inp['ack'] === true) parts.push('ack')
          if (inp['applied'] === true) parts.push('applied')
          out.push({ ...base, k: 'tool', g: '◇', gc: typeof inp['blocker'] === 'string' ? C.pink : typeof inp['question'] === 'string' ? C.yellow : C.lav, head: 'declared  ', hc: C.lav, text: fit(parts.join(' · ') || 'progress', w * 2), tc: C.dim })
          continue
        }
        if (BUS_TOOL.test(n)) continue
        const r = results.get(str(b['id']))
        out.push({
          ...base,
          k: 'tool',
          g: '⏺',
          gc: r === undefined ? C.yellow : r.isError ? C.pink : C.mint,
          head: n === 'TodoWrite' ? 'Update Todos' : n,
          arg: toolArg(n, b['input']),
          body: r === undefined ? [{ p: '⎿', t: 'running…', c: C.yellow }] : resultBody(n, b['input'], r.text, r.isError, w - 4),
        })
      }
    }
  }
  return out
}

export const filterTab = (lines: readonly TxLine[], tab: TxTab): TxLine[] =>
  tab === 'tools' ? lines.filter(l => l.k === 'tool') : tab === 'reasoning' ? lines.filter(l => l.k === 'think') : [...lines]

/** Lines the transcript keeps when no conversation can be read: the facts the bus recorded. */
export const fallbackLines = (a: AgentRec, name: string): TxLine[] => {
  const base = { head: '', hc: C.text, arg: '', text: '', tc: C.text, italic: false, body: [] as TxBody[] }
  const out: TxLine[] = [{ ...base, k: 'user', g: '›', gc: C.faint, head: `master → ${name}  `, hc: C.master, text: a.description }]
  for (const r of a.toolLog ?? []) out.push({ ...base, k: 'tool', g: '⏺', gc: r.ok === false ? C.pink : r.ok ? C.mint : C.yellow, head: r.tool, arg: r.arg ? `(${r.arg})` : '', body: [{ p: '⎿', t: r.ok === undefined ? 'running…' : r.ok ? `done in ${((r.ms ?? 0) / 1000).toFixed(1)}s` : 'failed', c: r.ok === false ? C.pink : C.dim }] })
  return out
}

// ---- Wardrobe view model (for /costume side panel and terminal)

// the master's antics in the wardrobe, one after another; each is a short play
const ANTICS = [['master.dance', 12], ['master.wave', 12], ['master.hop', 8]] as const

/** What a costume's crab does in the wardrobe: the master clowns around, one in the rotation walks, one out of it sleeps. */
export const previewMood = (isMaster: boolean, active: boolean, tick: number): { mood: string; t: number } => {
  if (isMaster) {
    const [mood, ticks] = ANTICS[Math.floor(tick / 24) % ANTICS.length] as (typeof ANTICS)[number]
    return { mood, t: tick % 24 < ticks ? tick % 24 : ticks - 1 }
  }
  return { mood: active ? 'walk' : 'sleep', t: tick }
}


